<?php
session_start(); require_once 'GEX-EC-05-SCRUM-Sprint-3-Desarrollo-ConfiguracionDeConexion-20261007-V1.0.php';
if (!isset($_SESSION['usuario_id']) || ($_SESSION['usuario_rol'] ?? '') !== 'Auditor') { header('Location: GEX-EC-05-SCRUM-Sprint-3-Desarrollo-PanelPrincipal-20261007-V1.0.php'); exit(); }
$stmt = $pdo->query('SELECT id, evento, solicitud_id, usuario_id, actor_rol, campo, valor_anterior, valor_nuevo, fecha_evento FROM auditoria_eventos ORDER BY fecha_evento DESC, id DESC'); $eventos = $stmt->fetchAll(PDO::FETCH_ASSOC);
function actorCodificado(?int $usuarioId): string { return $usuarioId ? 'ACT-' . strtoupper(substr(hash('sha256', 'auditoria-' . $usuarioId), 0, 10)) : 'SISTEMA'; }
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Historial de auditoría - Soporte</title><link rel="stylesheet" href="GEX-EC-05-SCRUM-Sprint-3-Desarrollo-EstilosDeInterfaz-20261007-V1.0.css"></head><body><div class="dashboard-layout"><?php include 'GEX-EC-05-SCRUM-Sprint-3-Desarrollo-MenuDeNavegacion-20261007-V1.0.php'; ?><div class="main-wrapper"><header class="topbar"><div class="topbar-title"><h2>Historial de auditoría</h2></div><div class="topbar-user"><span><strong><?php echo htmlspecialchars($_SESSION['usuario_nombre']); ?></strong></span><span class="user-badge">Auditor</span><a href="GEX-EC-05-SCRUM-Sprint-3-Desarrollo-CierreDeSesion-20261007-V1.0.php" class="btn-logout">Cerrar Sesión</a></div></header><main class="content-area"><div class="page-heading"><div><h1>Eventos registrados</h1><p>Consulta de solo lectura. Los actores están codificados y no se muestra texto libre.</p></div></div><div class="ui-card"><div class="table-wrapper"><table class="modern-table"><thead><tr><th>Fecha</th><th>Evento</th><th>Solicitud</th><th>Actor codificado</th><th>Campo</th><th>Valor anterior</th><th>Valor nuevo</th></tr></thead><tbody><?php if (!$eventos): ?><tr><td colspan="7" class="empty-table">No hay eventos registrados.</td></tr><?php else: ?><?php foreach ($eventos as $evento): ?><tr><td><?php echo htmlspecialchars(date('d/m/Y H:i:s', strtotime($evento['fecha_evento']))); ?></td><td><?php echo htmlspecialchars($evento['evento']); ?></td><td><?php echo $evento['solicitud_id'] ? '#' . (int) $evento['solicitud_id'] : 'General'; ?></td><td><?php echo htmlspecialchars(actorCodificado($evento['usuario_id'])); ?><small><?php echo htmlspecialchars($evento['actor_rol'] ?? ''); ?></small></td><td><?php echo htmlspecialchars($evento['campo'] ?? ''); ?></td><td><?php echo htmlspecialchars($evento['valor_anterior'] ?? ''); ?></td><td><?php echo htmlspecialchars($evento['valor_nuevo'] ?? ''); ?></td></tr><?php endforeach; ?><?php endif; ?></tbody></table></div></div></main></div></div></body></html>
